  "An MCP Access Group is a set of users or teams that have permission to access specific MCP servers. Use access groups to control and organize who can connect to which servers.": "MCP Access Group 是一组有权访问特定 MCP 服务器的用户或团队。使用 Access Group 控制和组织谁可以连接到哪些服务器。",
