  "Any path after {0} will be appended to the target URL": "{0} 之后的任何路径都会追加到目标 URL",
  "Anyone who can reach the gateway can call this server without a LiteLLM key. The caller's Authorization header is forwarded to the upstream verbatim, per-key and per-team rate limits and spend tracking do not apply, and the upstream is fully responsible for authenticating callers. Choose OAuth Delegate instead if callers should still authenticate to LiteLLM.": "任何能够访问网关的人都可以在无需 LiteLLM key 的情况下调用此服务器。调用方的 Authorization 请求头会原样转发至上游，按 key 和按团队的速率限制及费用跟踪不适用，且上游全权负责认证调用方。如果调用方仍应通过 LiteLLM 认证，请选择 OAuth Delegate。",
  "Applied to every new internal user created through SSO or the user management APIs.": "应用于通过 SSO 或用户管理 API 创建的每个新内部用户。",
