  "Callers bring their own upstream token for this auth type, so LiteLLM never stores tokens. To preview tools and configure the tool allowlist, authorize against the upstream here: the token stays in this browser session only and is never saved to LiteLLM. An OAuth app configured below IS saved with the server, so internal users who authorize from the Tools page go through it.": "此认证类型下，调用方自带上游令牌，因此 LiteLLM 不会存储令牌。要预览工具并配置工具允许列表，请在此向上游授权：令牌仅保留在当前浏览器会话中，绝不会保存到 LiteLLM。下方配置的 OAuth 应用会随服务器一起保存，因此从 Tools 页面授权的内部用户会通过该应用。",
