  "Choose Machine-to-Machine (M2M) or Interactive (PKCE) so LiteLLM authenticates it the way you intend, then save. Until it is set, LiteLLM falls back to interactive per-user auth and treats a machine-to-machine credential shape conservatively.": "请选择 Machine-to-Machine (M2M) 或 Interactive (PKCE)，让 LiteLLM 按您预期的方式进行认证，然后保存。在设置前，LiteLLM 会回退为交互式按用户认证，并谨慎处理机器到机器的凭据形式。",
