  "Choose how the proxy authenticates with this MCP server. M2M is for server-to-server communication using client credentials. Interactive (PKCE) is for user-facing flows that require browser-based authorization.": "选择代理如何与此 MCP 服务器认证。M2M 用于通过客户端凭据进行的服务器间通信；Interactive (PKCE) 用于需要基于浏览器授权的面向用户流程。",
  "Choose how to apply the margin: percentage-based or fixed amount": "选择加价的应用方式：基于百分比或固定金额",
