  "How long to cache each user's OAuth access token in Redis before evicting it (never longer than the token's own expires_in). Leave blank to derive the TTL from the token's expires_in, or fall back to the 12-hour default.": "在 Redis 中缓存每位用户 OAuth 访问令牌的时长，淘汰前绝不会超过令牌自身的 expires_in。留空则从令牌 expires_in 推导 TTL，或回退到默认的 12 小时。",
  "How much each signal contributes to the score. Absolute multipliers, so the total need not be 1.00.": "各信号对分数的贡献程度。使用绝对乘数，因此总和不必为 1.00。",
