  "It learns from how each conversation actually goes: does the user have to rephrase or correct the model, does it get stuck repeating itself, does it run out of tool calls, does the user seem satisfied. Combined with cost, this live feedback shifts future routing toward the models that are actually working well, and improves as more conversations come in. Until there's enough feedback, it defaults to the classified tier's model.": "它会从每次对话的实际表现中学习：用户是否需要重述或纠正、模型是否反复重复、是否耗尽工具调用、用户是否满意。结合成本，这种实时反馈会让后续路由更倾向实际表现更好的模型，并随对话增多持续优化；反馈不足时则回退到分级对应的模型。",
  "JSON": "JSON",
  "JSON metadata for the vector store": "Vector Store 的 JSON 元数据",
  "JSON metadata for the vector store (optional)": "Vector Store 的 JSON 元数据（可选）",
  "JSON object forwarded to the guardrail as request_data['metadata']. Custom guardrails can read per-request configuration from it.": "作为 request_data['metadata'] 转发给 guardrail 的 JSON 对象。自定义 guardrails 可从中读取按请求的配置。",
  "JSON object merged into litellm_params. e.g. forward_api_key, headers, model, unreachable_fallback": "合并到 litellm_params 的 JSON 对象。例如 forward_api_key、headers、model、unreachable_fallback",
  "JSON object of key-value rules checked against the OAuth token response before storing. Supports dot-notation for nested fields (e.g. {\"organization\": \"my-org\", \"team.id\": \"123\"}). Tokens that fail validation are rejected with HTTP 403.": "å­å¨åéå¯¹ OAuth ä»¤çååºæ£æ¥çé®å¼è§å JSON å¯¹è±¡ãæ¯æåµå¥å­æ®µçç¹è¡¨ç¤ºæ³ï¼ä¾å¦ {\"organization\": \"my-org\", \"team.id\": \"123\"}ï¼ãæªéè¿éªè¯çä»¤çä¼ä»¥ HTTP 403 æç»ã",
  "JSON object with additional information about this key. Used for tracking or custom logic": "包含此密钥附加信息的 JSON 对象。用于跟踪或自定义逻辑",
  "JavaScript (OpenAI SDK)": "JavaScript (OpenAI SDK)",
