  "Keep the old key valid for this many hours after creating the new one to allow for zero-downtime key rotation.": "创建新 Key 后保持旧 Key 在指定小时内仍然有效，以实现无停机 Key 轮换。",
  "Keeps a session on its first turn's model instead of re-classifying each turn. Also pins the deployment.": "让会话保持使用首轮的模型，而不是每轮重新分类，同时绑定部署。",
  "Keeps a session on the same deployment within a group, so provider prompt caches stay warm. Turn off to load-balance every turn.": "让会话在同一模型组内保持使用相同部署，使提供商提示词缓存保持温热。关闭后将对每一轮进行负载均衡。",
