  "Let the classifier read the assistant's replies, so difficulty the model stated rather than the user stays visible: a plan the assistant calls complex, approved with \"yes\", is classified on the work being approved. Context Window Size then counts the last N turns across both roles rather than the last N user turns.": "让分类器读取助手的回复，使模型而非用户所表述的难度保持可见：例如助手称某方案复杂、用户以“yes”确认时，将按被确认的工作分类。此时上下文窗口大小统计的是双方角色的最近 N 轮，而非仅用户的最近 N 轮。",
  "Lets OAuth-only clients like Claude Desktop register and sign in through the gateway. Turn off to relay the upstream server's own OAuth metadata instead (for clients pre-registered with the upstream IdP).": "允许仅支持 OAuth 的客户端（如 Claude Desktop）通过网关注册并登录。关闭后将转发上游服务器自身的 OAuth 元数据（适用于预先在上游 IdP 注册的客户端）。",
