  "LiteLLM is OpenAI Compatible. This means your API Key works with the OpenAI SDK. Just replace the base_url to point to your litellm proxy. Example Below": "LiteLLM 兼容 OpenAI API。这意味着你的 API Key 可与 OpenAI SDK 配合使用。只需将 base_url 替换为指向你的 litellm 代理，下面为示例",
