  "Optional system instructions for the model": "为模型提供的可选系统指令",
  "Optional. IAM role ARN to assume via STS before signing. If set, LiteLLM calls sts:AssumeRole to get temporary credentials.": "可选。签名前通过 STS 代入的 IAM 角色 ARN。设置后，LiteLLM 会调用 sts:AssumeRole 获取临时凭据。",
  "Optional. IAM role ARN to assume via STS before signing. If set, LiteLLM calls sts:AssumeRole to get temporary credentials. Uses ambient credentials (IAM role, env vars) as the source identity unless explicit keys are also provided.": "可选。签名前通过 STS 代入的 IAM 角色 ARN。设置后，LiteLLM 会调用 sts:AssumeRole 获取临时凭据。除非同时提供显式密钥，否则使用环境凭据（IAM 角色、环境变量）作为源身份。",
  "Optional. If not provided, falls back to the boto3 credential chain (IAM role, env vars, etc.).": "可选。未提供时，将回退到 boto3 凭据链（IAM 角色、环境变量等）。",
  "Optional. Only needed for temporary STS credentials.": "可选。仅临时 STS 凭据需要。",
  "Optional. Required if AWS Access Key ID is provided.": "可选。若提供 AWS Access Key ID，则必须提供。",
  "Optional. Session name for the AssumeRole call — appears in CloudTrail logs. Auto-generated if omitted.": "可选。AssumeRole 调用的会话名称——会显示在 CloudTrail 日志中。省略时自动生成。",
  "Optional: Add context or prompt for transcription...": "可选：为转写添加上下文或提示……",
  "Optional: Add terms to the built-in list to improve classification accuracy on the technical dimension. (e.g., udp, kafka, terraform).": "可选：向内置列表添加术语以提升技术维度的分类准确率（例如 udp、kafka、terraform）。",
  "Optional: Describe what this vector store contains": "可选：描述此 Vector Store 包含的内容",
  "Optional: Enter custom proxy URL (e.g., http://localhost:5000)": "可选：输入自定义代理 URL（例如 http://localhost:5000）",
  "Optional: Give your vector store a meaningful name": "可选：为你的 Vector Store 起一个有意义的名称",
  "Optional: Track costs for requests to this endpoint": "可选：跟踪发送到该端点请求的成本",
  "Optional: route requests containing specific keywords directly to a tier, e.g. route \"invoice, refund, billing\" to the medium tier.": "可选：将包含特定关键词的请求直接路由到某层级，例如将“invoice、refund、billing”路由到 medium 层级。",
  "Optional: when a user message contains one of these phrases, the request is bumped one tier higher than it would otherwise route to. Matching is case-sensitive, so \"LITELLM ESCALATE\" only fires on the exact, shouted form. Leave empty to disable.": "可选：当用户消息包含其中某个短语时，请求会比原本路由高一档。匹配区分大小写，因此“ LITELLM ESCALATE ”仅在完全一致的大写形式下触发。留空则禁用。",
  "Optionally assign this agent to a team. The agent and its key will belong to the selected team.": "可选：将此 Agent 分配到团队。该 Agent 及其密钥将归属于所选团队。",
  "Optionally select API provider credentials for this vector store eg. Bedrock API KEY": "可选为此 Vector Store 选择 API 提供商凭据，例如 Bedrock API KEY",
