  "What caching saved against paying the input rate for every token: the discount on tokens served from cache, less the premium providers charge to write a cache entry. Can be negative on traffic that writes more cache than it reuses.": "提示缓存相对按每个 Token 的输入费率计费所节省的费用：即缓存命中的 Token 所享受的折扣，扣除提供商写入缓存条目收取的溢价。当写入缓存的流量多于复用时，该值可能为负。",
