  "What the bot says aloud when this guardrail fires. Falls back to the default violation message if empty.": "此 guardrail 触发时 Bot 朗读的内容。留空则回退到默认违规消息。",
  "What this agent does": "这个 Agent 的用途",
  "What this skill does": "该技能的作用",
  "What this traffic would have cost had every request gone to the most expensive model the auto-router can route to, minus what it actually cost. Switching leaves the new model with a cold cache, so it pays to write the prompt again while the baseline is priced as already warm; a route that thrashes the cache can total below zero, and a genuine first turn, where neither side had anything cached, is undercounted.": "这部分流量若每个请求都发送到自动路由可路由的最贵模型需要多少费用，再减去实际花费。切换后新模型缓存是冷的，因此需要重新写入提示词，而基线按已命中缓存计价；频繁切换缓存的路由可能总计为负，而真正的首轮对话（两侧均无缓存）会被低估。",
  "When a model exceeds its per-model budget (model_max_budget), requests automatically reroute to fallback models instead of failing. Configure per-model budgets in Advanced Settings.": "当模型超过其单模型预算（model_max_budget）时，请求会自动改路由到回退模型，而不会失败。请在高级设置中配置单模型预算。",
  "When a reusable credential is used, it will appear as a tag prefixed with": "使用可复用凭据时，它会显示为前缀为",
  "When disabled, each request always uses the model assigned to its classified tier.": "禁用时，每个请求始终使用其分级对应的模型。",
  "When enabled, each user provides their own API key for this service. Keys are stored per-user and never shared.": "启用后，每位用户为此服务提供自己的 API Key。密钥按用户存储，绝不共享。",
  "When enabled, every API key can access this MCP server.": "启用后，每个 API key 都可以访问此 MCP 服务器。",
  "When enabled, only agents with reachable URLs are shown": "启用后，仅显示可访问 URL 的 Agent",
  "When enabled, this key will bypass any guardrails configured to run on every request (global guardrails)": "启用后，此密钥将绕过任何配置为在每个请求上运行的护栏（全局护栏）",
  "When enabled, this team will bypass any guardrails configured to run on every request (global guardrails)": "启用后，此团队将绕过配置为在每个请求上运行的所有护栏（全局护栏）",
  "When this key exceeds its max budget, throttle its TPM/RPM to the globally configured percentage instead of blocking access entirely. Requires budget_exceeded_throttle_percentage in litellm_settings and a TPM/RPM limit on the key.": "当此密钥超出其最大预算时，将其 TPM/RPM 限流到全局配置的百分比，而不是完全阻止访问。需要在 litellm_settings 中配置 budget_exceeded_throttle_percentage，并在密钥上设置 TPM/RPM 限制。",
